data.nginx.conf:
worker_processes 1;
pid /tmp/nginx.pid;
error_log /dev/stderr warn;
events { worker_connections 1024; }
http {
  client_body_temp_path /tmp/client;
  proxy_temp_path /tmp/proxy;
  uwsgi_temp_path /tmp/uwsgi;
  scgi_temp_path /tmp/scgi;
  fastcgi_temp_path /tmp/fastcgi;
  log_format lab escape=json '{"event":"http.edge","pod":"$hostname","request_id":"$sent_http_x_request_id","status":$status,"seconds":$request_time,"upstream_seconds":"$upstream_response_time","traffic":"$http_x_lab_traffic"}';
  access_log /dev/stdout lab;
  server {
    listen 8080;
    client_max_body_size 8k;
    client_body_timeout 10s;
    add_header X-Lab-API-Pod $hostname always;
    location / {
      include /etc/nginx/fastcgi_params;
      fastcgi_param SCRIPT_FILENAME /app/public/index.php;
      fastcgi_param DOCUMENT_ROOT /app/public;
      fastcgi_param HTTP_AUTHORIZATION $http_authorization;
      fastcgi_pass 127.0.0.1:9000;
      fastcgi_connect_timeout 2s;
      fastcgi_read_timeout 20s;
      fastcgi_next_upstream off;
    }
  }
}

worker_processes 1;
pid /tmp/nginx.pid;
error_log /dev/stderr warn;
events { worker_connections 2048; }
http {
  client_body_temp_path /tmp/client;
  proxy_temp_path /tmp/proxy;
  uwsgi_temp_path /tmp/uwsgi;
  scgi_temp_path /tmp/scgi;
  fastcgi_temp_path /tmp/fastcgi;
  log_format lab escape=json '{"event":"http.gateway","request_id":"$sent_http_x_request_id","api_pod":"$upstream_http_x_lab_api_pod","status":$status,"seconds":$request_time,"traffic":"$http_x_lab_traffic"}';
  access_log /dev/stdout lab;
  server {
    listen 8080;
    client_max_body_size 8k;
    client_body_timeout 10s;
    location = /gateway/live { access_log off; return 200 'alive'; }
    location / {
      proxy_pass http://api:8080;
      proxy_http_version 1.1;
      proxy_set_header Connection close;
      proxy_set_header Host $host;
      proxy_connect_timeout 2s;
      proxy_read_timeout 25s;
      proxy_next_upstream off;
    }
  }
}

