data.alertmanager.yml:
{
  "global": {
    "smtp_smarthost": "mailpit:1025",
    "smtp_from": "alertmanager@lab.test",
    "smtp_require_tls": false,
    "resolve_timeout": "1m"
  },
  "route": {
    "receiver": "local-mail",
    "group_by": [
      "alertname",
      "severity",
      "mode"
    ],
    "group_wait": "5s",
    "group_interval": "10s",
    "repeat_interval": "1h"
  },
  "receivers": [
    {
      "name": "local-mail",
      "email_configs": [
        {
          "to": "alerts@lab.test",
          "send_resolved": true,
          "headers": {
            "Subject": "[{{ .Status | toUpper }}][{{ .CommonLabels.severity }}] {{ .CommonLabels.alertname }} {{ .CommonLabels.mode }}"
          },
          "html": "<h2>{{ .Status }}: {{ .CommonLabels.alertname }}</h2><p>Local Laravel reliability lab. Mode: {{ .CommonLabels.mode }}</p>{{ range .Alerts }}<p>{{ .Annotations.summary }}</p><p>Runbook: {{ .Annotations.runbook }}</p>{{ end }}"
        }
      ]
    }
  ]
}

data.config.alloy:
discovery.kubernetes "lab" {
  role = "pod"
  namespaces {
    names = ["lab"]
  }
}
discovery.relabel "logs" {
  targets = discovery.kubernetes.lab.targets
  rule {
    source_labels = ["__meta_kubernetes_namespace"]
    target_label = "namespace"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_label_app"]
    target_label = "app"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_container_name"]
    target_label = "container"
  }
}
loki.source.kubernetes "lab" {
  targets = discovery.relabel.logs.output
  forward_to = [loki.write.local.receiver]
}
loki.write "local" {
  endpoint {
    url = "http://loki:3100/loki/api/v1/push"
  }
}

